const input = $json || {};

const sampleQueue = [
  {
    dispatchId: 'dsp_sample_1',
    chatId: '1938141471',
    text: '*Add International Social Mixer to calendar*\n\nApprove this action?',
    parseMode: 'Markdown',
    buttons: [
      { label: 'Approve', value: 'approve:social-1-calendar-2' },
      { label: 'Reject', value: 'reject:social-1-calendar-2' },
      { label: 'Alternative', value: 'alternative:social-1-calendar-2' }
    ],
    scheduledFor: null,
    approvalId: 'apr_sample_123',
    relatedActionId: 'social-1-calendar-2',
    status: 'preview_only'
  }
];

const queue =
  Array.isArray(input.telegramQueue)
    ? input.telegramQueue
    : Array.isArray(input.result?.channelDispatch?.telegramQueue)
      ? input.result.channelDispatch.telegramQueue
      : Array.isArray(input.channelDispatcherOutput?.result?.channelDispatch?.telegramQueue)
        ? input.channelDispatcherOutput.result.channelDispatch.telegramQueue
        : sampleQueue;

const metadata = {
  correlationId:
    input.metadata?.correlationId ||
    `telegram-connector-${Date.now()}`,
  dispatchEnabled:
    input.metadata?.dispatchEnabled === true,
  testMode:
    input.metadata?.testMode ?? true,
  ...input.metadata
};

return [{
  json: {
    queue,
    metadata
  }
}];

const queue = Array.isArray($json.queue) ? $json.queue : [];
const metadata = $json.metadata || {};
const items = [];

for (const entry of queue) {
  const chatId = entry.chatId ? String(entry.chatId) : '';
  const text = String(entry.text || '').trim();

  if (!chatId || !text) {
    items.push({
      json: {
        valid: false,
        shouldSend: false,
        dispatchId: entry.dispatchId || null,
        chatId,
        text,
        error: !chatId ? 'missing_chat_id' : 'missing_text',
        metadata
      }
    });
    continue;
  }

  const buttonText = Array.isArray(entry.buttons) && entry.buttons.length
    ? '\n\n' + entry.buttons
        .map(button => `[${button.label}] ${button.value}`)
        .join('\n')
    : '';

  items.push({
    json: {
      valid: true,
      shouldSend: metadata.dispatchEnabled === true,
      dispatchId: entry.dispatchId || null,
      chatId,
      text: `${text}${buttonText}`.slice(0, 4000),
      parseMode: entry.parseMode || 'Markdown',
      approvalId: entry.approvalId || null,
      relatedActionId: entry.relatedActionId || null,
      scheduledFor: entry.scheduledFor || null,
      metadata
    }
  });
}

return items.length
  ? items
  : [{
      json: {
        valid: false,
        shouldSend: false,
        error: 'empty_telegram_queue',
        metadata
      }
    }];

const original = $('Expand Telegram Queue').item.json || {};
const response = $json || {};

return [{
  json: {
    success: true,
    result: {
      mode: 'sent',
      dispatchId: original.dispatchId || null,
      chatId: original.chatId || null,
      approvalId: original.approvalId || null,
      relatedActionId: original.relatedActionId || null,
      telegramResponse: response,
      status: 'sent'
    },
    memoryUpdates: [{
      type: 'dispatch_history',
      operation: 'append',
      payload: {
        dispatchId: original.dispatchId || null,
        channel: 'telegram',
        destination: original.chatId || null,
        status: 'sent',
        createdAt: new Date().toISOString()
      }
    }],
    approvalRequests: [],
    logs: [{
      timestamp: new Date().toISOString(),
      workflow: 'Concierge OS - Telegram Channel Connector',
      level: 'info',
      correlationId: original.metadata?.correlationId || '',
      message: 'Telegram message sent.',
      details: {
        dispatchId: original.dispatchId || null,
        chatId: original.chatId || null
      }
    }],
    nextAction: {
      type: 'await_user_response',
      targetWorkflow: 'Concierge OS - Telegram Approval Response'
    },
    error: null
  }
}];

const item = $json || {};

return [{
  json: {
    success: item.valid === true,
    result: {
      mode: 'preview',
      dispatchId: item.dispatchId || null,
      chatId: item.chatId || null,
      text: item.text || '',
      approvalId: item.approvalId || null,
      relatedActionId: item.relatedActionId || null,
      status: item.valid ? 'preview_ready' : 'rejected',
      reason: item.error || 'dispatchEnabled is false'
    },
    memoryUpdates: item.valid ? [{
      type: 'dispatch_history',
      operation: 'append',
      payload: {
        dispatchId: item.dispatchId || null,
        channel: 'telegram',
        destination: item.chatId || null,
        status: 'preview_ready',
        createdAt: new Date().toISOString()
      }
    }] : [],
    approvalRequests: [],
    logs: [{
      timestamp: new Date().toISOString(),
      workflow: 'Concierge OS - Telegram Channel Connector',
      level: item.valid ? 'info' : 'warning',
      correlationId: item.metadata?.correlationId || '',
      message: item.valid
        ? 'Telegram payload prepared in preview mode.'
        : 'Telegram payload rejected.',
      details: {
        dispatchId: item.dispatchId || null,
        reason: item.error || 'dispatch disabled'
      }
    }],
    nextAction: {
      type: item.valid ? 'review_preview' : 'stop',
      targetWorkflow: null
    },
    error: item.valid ? null : {
      code: item.error || 'INVALID_TELEGRAM_PAYLOAD',
      message: 'Telegram payload is invalid.',
      retryable: false
    }
  }
}];
